using System.Windows;using AutoPecasERP.Data.Context;using AutoPecasERP.Services.Backup;using AutoPecasERP.Services.Seguranca;using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Desktop.Views;
public partial class SegurancaBackupWindow:Window{readonly ErpDbContext _db=new();public SegurancaBackupWindow(){InitializeComponent();Loaded+=Carregar;}async void Carregar(object s,RoutedEventArgs e){await new PermissaoService(_db).SemearAsync();AuditoriaGrid.ItemsSource=await _db.Auditorias.OrderByDescending(x=>x.Data).Take(1000).ToListAsync();PermissoesGrid.ItemsSource=await _db.PermissoesPerfil.OrderBy(x=>x.Perfil).ThenBy(x=>x.Modulo).ToListAsync();}
async void Backup_Click(object s,RoutedEventArgs e){try{var pasta=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"AutoPecasERP","Backups");var arq=await new BackupService().CriarAsync(pasta);new BackupService().ValidarBackup(arq);BackupInfo.Text=$"Backup criado e verificado:\n{arq}";}catch(Exception ex){MessageBox.Show(ex.Message,"Backup",MessageBoxButton.OK,MessageBoxImage.Error);}}}